from __future__ import annotations

import ipaddress


def evaluate(policies: list[dict], request: dict) -> dict:
    attrs = request.get("attrs") or {}
    principal = request.get("principal")
    groups = request.get("groups") or []
    action = request.get("action")
    resource = request.get("resource")

    principal_is_user = isinstance(principal, str) and principal.startswith("user:")
    action_parts = action.split(":", 1) if isinstance(action, str) and ":" in action else None
    resource_parts = resource.split("/") if isinstance(resource, str) else None

    def values_equal(left, right) -> bool:
        if isinstance(left, bool) or isinstance(right, bool):
            return isinstance(left, bool) and isinstance(right, bool) and left == right
        return left == right

    def match_principal(pattern) -> bool:
        if pattern == "*":
            return True
        if pattern == "user:*":
            return principal_is_user
        if pattern.startswith("user:"):
            return principal == pattern
        if pattern == "group:*":
            return len(groups) > 0
        if pattern.startswith("group:"):
            return pattern[6:] in groups
        return False

    def match_action(pattern) -> bool:
        if pattern == "*":
            return True
        if action_parts is None:
            return False
        if ":" not in pattern:
            return False

        p_service, p_verb = pattern.split(":", 1)
        r_service, r_verb = action_parts
        return (
            (p_service == "*" or p_service == r_service)
            and (p_verb == "*" or p_verb == r_verb)
        )

    def match_resource(pattern) -> bool:
        if not isinstance(pattern, str) or resource_parts is None:
            return False

        pat = pattern.split("/")
        res = resource_parts
        n = len(res)

        # next_row[j] means: remaining pattern after current segment
        # matches res[j:]
        next_row = [False] * (n + 1)
        next_row[n] = True

        for seg in reversed(pat):
            cur = [False] * (n + 1)

            if seg == "**":
                cur[n] = next_row[n]
                for j in range(n - 1, -1, -1):
                    cur[j] = next_row[j] or cur[j + 1]
            elif seg == "*":
                for j in range(n - 1, -1, -1):
                    cur[j] = next_row[j + 1]
            else:
                for j in range(n - 1, -1, -1):
                    if seg == res[j]:
                        cur[j] = next_row[j + 1]

            next_row = cur

        return next_row[0]

    def to_minutes(t: str) -> int:
        h, m = t.split(":")
        return int(h) * 60 + int(m)

    ip_address = None
    if "ip" in attrs:
        try:
            ip_address = ipaddress.ip_address(attrs["ip"])
        except ValueError:
            ip_address = None

    def conditions_hold(conditions) -> bool:
        if not conditions:
            return True

        if "ip_in" in conditions:
            if ip_address is None:
                return False

            for net in conditions["ip_in"]:
                try:
                    network = ipaddress.ip_network(net, strict=False)
                except ValueError:
                    continue
                if ip_address in network:
                    break
            else:
                return False

        if "mfa" in conditions:
            if not values_equal(attrs.get("mfa", False), conditions["mfa"]):
                return False

        if "time_between" in conditions:
            start_s, end_s = conditions["time_between"]
            start = to_minutes(start_s)
            end = to_minutes(end_s)

            time_value = attrs.get("time")
            if time_value is None:
                return False

            t = to_minutes(time_value)

            if start < end:
                if not (start <= t < end):
                    return False
            elif start > end:
                if not (t >= start or t < end):
                    return False
            # start == end: holds for any present time

        if "weekdays" in conditions:
            weekday = attrs.get("weekday")
            if weekday is None or weekday not in conditions["weekdays"]:
                return False

        if "tags_any" in conditions:
            tags = attrs.get("tags") or []
            if not any(tag in tags for tag in conditions["tags_any"]):
                return False

        if "tags_all" in conditions:
            tags = attrs.get("tags") or []
            for tag in conditions["tags_all"]:
                if tag not in tags:
                    return False

        if "attr_equals" in conditions:
            for key, value in conditions["attr_equals"].items():
                if key not in attrs:
                    return False
                if not values_equal(attrs[key], value):
                    return False

        return True

    matched_policies = []
    for pol in policies:
        if (
            any(match_principal(p) for p in pol.get("principals", []))
            and any(match_action(a) for a in pol.get("actions", []))
            and any(match_resource(r) for r in pol.get("resources", []))
            and conditions_hold(pol.get("conditions") or {})
        ):
            matched_policies.append(pol)

    matched_ids = sorted(str(pol["id"]) for pol in matched_policies)

    emergency = attrs.get("emergency", False) is True
    overridden_count = 0
    active_policies = []

    for pol in matched_policies:
        if (
            emergency
            and pol.get("effect") == "deny"
            and not (pol.get("hard", False) is True)
        ):
            overridden_count += 1
        else:
            active_policies.append(pol)

    if not active_policies:
        return {
            "decision": "deny",
            "policy": None,
            "reason": "no-match",
            "obligations": [],
            "matched": matched_ids,
        }

    def priority_of(pol) -> int:
        pr = pol.get("priority", 0)
        return 0 if pr is None else pr

    winner = min(
        active_policies,
        key=lambda p: (
            -priority_of(p),
            0 if p.get("effect") == "deny" else 1,
            str(p["id"]),
        ),
    )

    decision = winner["effect"]
    reason = "emergency" if decision == "allow" and overridden_count > 0 else "explicit"

    if decision == "deny":
        obligations = []
    else:
        winner_priority = priority_of(winner)
        obs = set()

        for pol in active_policies:
            if (
                pol.get("effect") == "allow"
                and priority_of(pol) == winner_priority
            ):
                for obligation in pol.get("obligations", []):
                    obs.add(obligation)

        if reason == "emergency":
            obs.add("audit")

        obligations = sorted(obs)

    return {
        "decision": decision,
        "policy": winner["id"],
        "reason": reason,
        "obligations": obligations,
        "matched": matched_ids,
    }
